const body = $input.first().json.body || {};
const query = $input.first().json.query || {};

const leadId = body.lead_id || query.lead_id || '';
const companyName = body.company_name || query.company_name || '';
const website = body.website || query.website || '';
const industry = body.industry || query.industry || '';
const contactName = body.contact_name || query.contact_name || '';
const notes = body.notes || query.notes || '';

if (!companyName) {
  throw new Error('company_name is required');
}

return [{
  json: {
    lead_id: leadId,
    company_name: companyName,
    website: website,
    industry: industry,
    contact_name: contactName,
    notes: notes
  }
}];

const data = $input.first().json;
const companyName = data.company_name;
const website = data.website || '';
const serpApiKey = 'b183c082b67f0971673dbab7ce0a14883f75e5012d09720d17c540efce67bc39';

// Search 1: Brand website content
let websiteContent = '';
try {
  let domain = '';
  if (website) {
    try {
      domain = new URL(website.startsWith('http') ? website : `https://${website}`).hostname.replace('www.', '');
    } catch(e) { domain = website.replace(/https?:\/\//, '').replace('www.', '').split('/')[0]; }
  }
  const siteQuery = domain ? `site:${domain}` : `"${companyName}" products about`;
  const resp1 = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://serpapi.com/search.json?engine=google&q=${encodeURIComponent(siteQuery)}&num=10&api_key=${serpApiKey}`,
    json: true
  });
  const results = resp1.organic_results || [];
  websiteContent = results.map(r => `${r.title}: ${r.snippet || ''}`).join('\n');
} catch (e) {
  websiteContent = `Error: ${e.message}`;
}

// Search 2: Brand ads and creative
let adsContent = '';
try {
  const adsQuery = `"${companyName}" ads OR advertisement OR creative OR campaign`;
  const resp2 = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://serpapi.com/search.json?engine=google&q=${encodeURIComponent(adsQuery)}&num=10&api_key=${serpApiKey}`,
    json: true
  });
  const results = resp2.organic_results || [];
  adsContent = results.map(r => `${r.title}: ${r.snippet || ''}`).join('\n');
} catch (e) {
  adsContent = `Error: ${e.message}`;
}

// Search 3: Social media and reviews
let socialContent = '';
try {
  const socialQuery = `"${companyName}" instagram OR facebook OR youtube review OR reviews`;
  const resp3 = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://serpapi.com/search.json?engine=google&q=${encodeURIComponent(socialQuery)}&num=5&api_key=${serpApiKey}`,
    json: true
  });
  const results = resp3.organic_results || [];
  socialContent = results.map(r => `${r.title}: ${r.snippet || ''}`).join('\n');
} catch (e) {
  socialContent = `Error: ${e.message}`;
}

return [{
  json: {
    ...data,
    website_content: websiteContent,
    ads_content: adsContent,
    social_content: socialContent
  }
}];

const data = $input.first().json;

const systemPrompt = `You are Jeet, a sharp creative strategist at Cosmisk — a UGC and performance ad agency in India. You analyze brands' current ads and tell them exactly what's wrong and how to fix it.

Your tone: Direct, confident, casual-professional. Like a smart friend who works in advertising giving honest feedback over coffee. NOT like a corporate consultant or AI assistant.

STRICT RULES:
- NEVER use these words/phrases: "unparalleled", "dramatically", "game-changer", "unlock", "leverage", "amplify", "resonate", "captivate", "delve", "comprehensive", "cutting-edge", "incredible", "powerful promise", "deeply", "genuinely impressed", "massive opportunity"
- NEVER make up statistics. No "2-3x ROAS" or "30-60% CPA reduction" unless you have actual data.
- NEVER say "we specialize in helping brands like X" — it's obvious and template-y
- Be BRUTALLY specific. Reference actual products, actual pages, actual campaigns you found in the search data
- Improvements must include EXACT script lines a creator would say, not vague descriptions
- The email should read like one person wrote it to another person, not like a sales template
- Keep sentences short. No compound sentences with semicolons.
- If you can't find enough data to be specific, say so honestly instead of making generic observations

Cosmisk services: UGC video ads, AI-generated ad variations, mashup ads, Meta/Google media buying, ad account audits.`;

const userPrompt = `Analyze this brand for a Creative Tear-Down:

BRAND: ${data.company_name}
WEBSITE: ${data.website || 'Unknown'}
INDUSTRY: ${data.industry || 'Unknown'}
CONTACT: ${data.contact_name || 'Unknown'}

WEBSITE DATA:
${data.website_content || 'No data'}

ADS/MARKETING DATA:
${data.ads_content || 'No data'}

SOCIAL DATA:
${data.social_content || 'No data'}

NOTES: ${data.notes || 'None'}

---

Return ONLY valid JSON (no markdown, no code fences):

{
  "brand_overview": {
    "name": "",
    "industry": "",
    "products": ["be specific - actual product names"],
    "target_audience": "be specific - who exactly buys this",
    "positioning": "one sentence, how they see themselves",
    "estimated_size": "startup/growing/established/enterprise"
  },
  "creative_assessment": {
    "strengths": ["2-3 specific things they do well - reference actual campaigns/pages/products you found"],
    "weaknesses": ["3-4 specific gaps - what exactly is wrong with their current approach"],
    "visual_style": "describe what their ads/website actually look like",
    "hook_effectiveness": "low/medium/high",
    "cta_clarity": "low/medium/high",
    "social_proof_usage": "none/weak/moderate/strong",
    "ugc_usage": "none/minimal/moderate/heavy",
    "overall_grade": "A/B/C/D/F"
  },
  "ugc_opportunity": {
    "score": 1-10,
    "primary_angle": "one specific reason UGC would work for them - not generic",
    "formats": ["pick 2-3 that actually fit, not all of them"],
    "creator_profile": "specific - age range, gender, vibe, what they'd look like",
    "platforms": ["pick 1-2 that matter most"],
    "estimated_impact": "be honest and specific about what would change"
  },
  "improvements": [
    {
      "area": "one of: hooks/scripts/visuals/ctas/social-proof",
      "current_state": "what they actually do right now - be specific",
      "recommendation": "what to do instead - one clear sentence",
      "example": "WRITE THE ACTUAL SCRIPT LINE or describe the exact visual. Not vague. Example: 'Camera on face, no makeup: Hey so I have really oily skin and I've tried literally everything. My friend told me to try [Product Name] and honestly? Look at my skin right now. It's been 3 weeks.'",
      "expected_lift": "be honest - 'better engagement' is fine, don't make up percentages"
    }
  ],
  "outreach": {
    "subject_line": "short, specific, no buzzwords - like a real person wrote it",
    "email_body": "Write like a real person. 2-3 short paragraphs max. Reference ONE specific thing you noticed about their brand. Don't oversell. End with asking for a quick chat, not 'book a free strategy call'. No 'Dear [Contact Name]' - use 'Hey' or 'Hi'.",
    "instagram_dm": "2 sentences max. Casual. Like you're DMing a brand you actually follow.",
    "whatsapp_message": "2 sentences. Get to the point.",
    "key_stat": "one honest, specific observation about their brand - not a made-up industry stat"
  }
}`;

return [{
  json: {
    ...data,
    requestBody: {
      systemInstruction: { parts: [{ text: systemPrompt }] },
      contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
      generationConfig: {
        temperature: 0.8,
        maxOutputTokens: 8192
      }
    }
  }
}];

const originalData = $('ctd-build-prompt').first().json;
const geminiText = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || '';

// Robust JSON extraction - strip markdown fences
let cleaned = geminiText;
// Remove leading ```json or ``` 
if (cleaned.trimStart().startsWith('`')) {
  const firstNewline = cleaned.indexOf('\n');
  if (firstNewline > -1) cleaned = cleaned.substring(firstNewline + 1);
}
// Remove trailing ```
const lastBacktick = cleaned.lastIndexOf('`');
if (lastBacktick > -1 && cleaned.substring(lastBacktick).trim().match(/^`{1,3}\s*$/)) {
  cleaned = cleaned.substring(0, lastBacktick);
}
cleaned = cleaned.trim();

// Parse JSON
let teardown = {};
try {
  teardown = JSON.parse(cleaned);
} catch (e) {
  // Try extracting the largest JSON object
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try { teardown = JSON.parse(match[0]); } catch (e2) {
      // Truncated JSON - try to salvage by closing brackets
      let salvage = match[0];
      let openBraces = (salvage.match(/\{/g) || []).length;
      let closeBraces = (salvage.match(/\}/g) || []).length;
      let openBrackets = (salvage.match(/\[/g) || []).length;
      let closeBrackets = (salvage.match(/\]/g) || []).length;
      // Remove trailing comma or incomplete value
      salvage = salvage.replace(/,\s*$/, '');
      salvage = salvage.replace(/,\s*"[^"]*"?\s*$/, '');
      salvage = salvage.replace(/:\s*"[^"]*$/, ': "..."');
      // Close brackets
      for (let i = 0; i < openBrackets - closeBrackets; i++) salvage += ']';
      for (let i = 0; i < openBraces - closeBraces; i++) salvage += '}';
      try { teardown = JSON.parse(salvage); } catch(e3) {
        teardown = { error: 'Parse failed', raw: geminiText.substring(0, 2000) };
      }
    }
  } else {
    teardown = { error: 'No JSON found', raw: geminiText.substring(0, 2000) };
  }
}

const overview = teardown.brand_overview || {};
const assessment = teardown.creative_assessment || {};
const opportunity = teardown.ugc_opportunity || {};
const improvements = teardown.improvements || [];
const outreach = teardown.outreach || {};

// Build human-readable notes for Airtable
const notesLines = [
  '=== CREATIVE TEAR-DOWN ===',
  `Brand: ${overview.name || originalData.company_name} | Industry: ${overview.industry || originalData.industry || 'N/A'}`,
  `Grade: ${assessment.overall_grade || 'N/A'} | UGC Score: ${opportunity.score || 'N/A'}/10`,
  `Products: ${(overview.products || []).join(', ')}`,
  `Target: ${overview.target_audience || 'N/A'}`,
  `Positioning: ${overview.positioning || 'N/A'}`,
  '',
  `STRENGTHS: ${(assessment.strengths || []).join(' | ')}`,
  `WEAKNESSES: ${(assessment.weaknesses || []).join(' | ')}`,
  '',
  'UGC OPPORTUNITY:',
  `  Angle: ${opportunity.primary_angle || 'N/A'}`,
  `  Formats: ${(opportunity.formats || []).join(', ')}`,
  `  Creator: ${opportunity.creator_profile || 'N/A'}`,
  `  Platforms: ${(opportunity.platforms || []).join(', ')}`,
  `  Impact: ${opportunity.estimated_impact || 'N/A'}`,
  '',
  'IMPROVEMENTS:'
];

for (let i = 0; i < improvements.length; i++) {
  const imp = improvements[i];
  notesLines.push(`${i+1}. ${(imp.area || '').toUpperCase()}`);
  notesLines.push(`   Now: ${imp.current_state || 'N/A'}`);
  notesLines.push(`   Do: ${imp.recommendation || 'N/A'}`);
  notesLines.push(`   Ex: ${imp.example || 'N/A'}`);
  notesLines.push(`   Lift: ${imp.expected_lift || 'N/A'}`);
}

notesLines.push('');
notesLines.push('=== OUTREACH ===');
notesLines.push(`Subject: ${outreach.subject_line || 'N/A'}`);
notesLines.push(`Key Stat: ${outreach.key_stat || 'N/A'}`);
notesLines.push('');
notesLines.push('EMAIL:');
notesLines.push(outreach.email_body || 'N/A');
notesLines.push('');
notesLines.push('INSTAGRAM DM:');
notesLines.push(outreach.instagram_dm || 'N/A');
notesLines.push('');
notesLines.push('WHATSAPP:');
notesLines.push(outreach.whatsapp_message || 'N/A');

const notesText = notesLines.join('\n');

// Build Slack message
const slackLines = [
  `*Creative Tear-Down: ${overview.name || originalData.company_name}*`,
  `Industry: ${overview.industry || 'N/A'} | Grade: *${assessment.overall_grade || 'N/A'}* | UGC Score: *${opportunity.score || 'N/A'}/10*`,
  '',
  `*Strengths:* ${(assessment.strengths || []).slice(0, 3).join(', ')}`,
  `*Weaknesses:* ${(assessment.weaknesses || []).slice(0, 3).join(', ')}`,
  '',
  '*Top Improvements:*'
];
for (let i = 0; i < Math.min(improvements.length, 3); i++) {
  slackLines.push(`>${i+1}. *${improvements[i].area || ''}*: ${improvements[i].recommendation || ''}`);
}
slackLines.push('');
slackLines.push(`*Outreach Subject:* ${outreach.subject_line || 'N/A'}`);
slackLines.push(`*Key Stat:* ${outreach.key_stat || 'N/A'}`);
slackLines.push('');
slackLines.push(`_Lead: ${originalData.lead_id || 'no ID'} | Tear-down stored on record_`);

return [{
  json: {
    lead_id: originalData.lead_id || '',
    company_name: originalData.company_name,
    teardown_json: JSON.stringify(teardown),
    notes_text: notesText,
    slack_message: slackLines.join('\n'),
    outreach_email: outreach.email_body || '',
    outreach_subject: outreach.subject_line || '',
    outreach_dm: outreach.instagram_dm || '',
    outreach_whatsapp: outreach.whatsapp_message || '',
    ugc_score: opportunity.score || 0
  }
}];

const data = $input.first().json;

// Skip if tear-down had errors
if (!data.teardown_json || data.teardown_json.includes('"error"')) {
  return [{ json: { learningsCount: 0 } }];
}

let teardown = {};
try { teardown = JSON.parse(data.teardown_json); } catch(e) {
  return [{ json: { learningsCount: 0 } }];
}

const overview = teardown.brand_overview || {};
const assessment = teardown.creative_assessment || {};
const opportunity = teardown.ugc_opportunity || {};
const improvements = teardown.improvements || [];

const systemPrompt = `You extract GENERALIZABLE creative strategy learnings from brand tear-down analyses. These learnings will be used by AI agents writing UGC ad scripts, outreach messages, and content strategies.

CRITICAL: Only extract insights that GENERALIZE beyond this specific brand. "Brand X has weak CTAs" is NOT generalizable. "D2C skincare brands that use question hooks get higher engagement than statement hooks" IS generalizable.

Categories:
- hook_patterns: What hook styles/structures work or fail for certain industries/audiences
- creative_strategy: Broader creative approach insights (UGC vs polished, testimonial vs demo, etc.)
- industry_trend: Patterns you see in how brands in this industry market
- audience_insight: What certain audience segments respond to`;

const userPrompt = `TEAR-DOWN DATA:

Brand: ${overview.name || data.company_name}
Industry: ${overview.industry || 'Unknown'}
Audience: ${overview.target_audience || 'Unknown'}
Positioning: ${overview.positioning || 'Unknown'}
Products: ${(overview.products || []).join(', ')}

Creative Grade: ${assessment.overall_grade || 'N/A'}
Hook Effectiveness: ${assessment.hook_effectiveness || 'N/A'}
CTA Clarity: ${assessment.cta_clarity || 'N/A'}
Social Proof: ${assessment.social_proof_usage || 'N/A'}
UGC Usage: ${assessment.ugc_usage || 'N/A'}
UGC Score: ${opportunity.score || 'N/A'}/10

Strengths: ${(assessment.strengths || []).join(' | ')}
Weaknesses: ${(assessment.weaknesses || []).join(' | ')}

UGC Angle: ${opportunity.primary_angle || 'N/A'}
Creator Profile: ${opportunity.creator_profile || 'N/A'}

Improvements Found:
${improvements.map((imp, i) => `${i+1}. ${imp.area}: Current: ${imp.current_state} -> Recommended: ${imp.recommendation}`).join('\n')}

---

Extract 1-3 GENERALIZABLE learnings. For each:
- Title: One sentence, specific pattern (e.g., "Direct-to-camera hooks outperform text overlay hooks for supplement brands")
- Category: hook_patterns | creative_strategy | industry_trend | audience_insight
- Insight: 2-3 sentences explaining the pattern and why it works
- Evidence: Reference the specific brand data that supports this (brand name, grade, scores)
- Confidence: 0.5-0.8 (single brand = lower confidence, obvious pattern = higher)

Return ONLY valid JSON (no markdown fences):
{
  "learnings": [
    {
      "title": "...",
      "category": "...",
      "insight": "...",
      "evidence": "...",
      "confidence": 0.6
    }
  ]
}

If nothing generalizable, return: { "learnings": [] }`;

const requestBody = {
  systemInstruction: { parts: [{ text: systemPrompt }] },
  contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
  generationConfig: { temperature: 0.3, maxOutputTokens: 2048, thinkingConfig: { thinkingBudget: 0 } }
};

return [{ json: { ...data, learningRequestBody: JSON.stringify(requestBody) } }];

const upstreamData = $('ctd-build-learning-prompt').first().json;

// If upstream returned learningsCount: 0, skip
if (upstreamData.learningsCount === 0) {
  return [{ json: { learningsCount: 0 } }];
}

const geminiResp = $('ctd-gemini-learnings').first().json;
const geminiText = geminiResp.candidates?.[0]?.content?.parts?.[0]?.text || '';
let cleaned = geminiText.replace(/^```json\s*/i, '').replace(/^```\s*/m, '').replace(/\s*```\s*$/m, '').trim();

let parsed = { learnings: [] };
try {
  parsed = JSON.parse(cleaned);
} catch(e) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try { parsed = JSON.parse(match[0]); } catch(e2) {}
  }
}

const newLearnings = parsed.learnings || [];
if (newLearnings.length === 0) {
  return [{ json: { learningsCount: 0 } }];
}

// Get existing learnings for dedup
const existingResp = $input.first().json;
const existing = (existingResp.records || []).map(r => ({
  title: (r.fields?.title || '').toLowerCase(),
  insight: (r.fields?.insight || '').toLowerCase()
}));

// Dedup: >50% word overlap
const deduped = newLearnings.filter(nl => {
  const nlWords = (nl.title + ' ' + nl.insight).toLowerCase().split(/\s+/);
  for (const ex of existing) {
    const exWords = (ex.title + ' ' + ex.insight).split(/\s+/);
    const overlap = nlWords.filter(w => w.length > 3 && exWords.includes(w)).length;
    const ratio = overlap / Math.max(nlWords.length, 1);
    if (ratio > 0.5) return false;
  }
  return true;
});

if (deduped.length === 0) {
  return [{ json: { learningsCount: 0 } }];
}

const records = deduped.slice(0, 3).map(l => ({
  fields: {
    title: l.title,
    source_agent: 'creative_teardown',
    category: l.category || 'creative_strategy',
    insight: l.insight,
    evidence: '[Tear-down: ' + (upstreamData.company_name || 'Unknown') + '] ' + (l.evidence || ''),
    confidence: Math.min(Math.max(l.confidence || 0.6, 0.3), 0.9),
    active: true,
    created_at: new Date().toISOString()
  }
}));

return [{ json: {
  learningsCount: records.length,
  airtable_body: JSON.stringify({ records })
}}];
